{
  "title": "The Glass Diver's Escape",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara traces a path through ruined streets.",
      "visual_description": "Mara the Cartographer unrolls a stained map on a crumbling fountain, her brass compass glinting in the pale light of the ruined royal city.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of the castle gates.",
      "visual_description": "The Oracle Lamp's single glowing eye flickers as it speaks, casting long shadows across the cracked cobblestones near the massive, rusted castle gates.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox scouts ahead through debris.",
      "visual_description": "Tin Fox scurries over fallen stone blocks, its key-wind tail ticking softly, blue glass eyes scanning for movement under the tattered royal banners.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver joins the group at the fountain.",
      "visual_description": "The Glass Diver steps through a shattered window, diving helmet clear, coat reflecting the broken lights of the city as he approaches Mara and the lamp.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 5,
      "caption": "They find the Sleeping Tax Collector at his post.",
      "visual_description": "The Sleeping Tax Collector snores loudly, head resting on a ledger book, stamped papers stuck to his sleeves, oblivious to the group's approach in a roofless building.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "Tin Fox discovers a hidden passage behind a banner.",
      "visual_description": "Tin Fox nudges a torn royal banner aside, revealing a narrow, dark passage beneath the city wall, its metal nose glowing faintly.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 7,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The Oracle Lamp's flame shrinks and its eye widens as it gazes at a twisted tower in the distance, its spire shrouded in unnatural mist.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "They enter the passage beneath the city.",
      "visual_description": "The group crouches as they move through the damp, narrow tunnel, the Glass Diver's helmet reflecting dim light, Tin Fox leading with a soft click.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The Sleeping Tax Collector is left behind.",
      "visual_description": "The Sleeping Tax Collector remains snoring under the torn banner, still clutching his ledger, as the others move deeper into the passage.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 10,
      "caption": "They emerge near the castle gates.",
      "visual_description": "The group exits the passage into a courtyard, facing the towering castle gates, now warped and half-open, with strange runes glowing on the metal.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Tin Fox triggers a silent alarm.",
      "visual_description": "Tin Fox steps on a pressure plate; a faint humming rises from the ground, and armored patrols begin to stir in the distance, their metal boots clanking.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver opens a magic door with reflection.",
      "visual_description": "The Glass Diver presses his helmet against a smooth, mirror-like door; the surface ripples, and he steps through, pulling the others into a hidden chamber.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "Mara reads a forgotten map in the chamber.",
      "visual_description": "Mara unrolls another map found in the chamber, tracing a route to an escape bridge, her ink-stained fingers trembling with urgency.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The Oracle Lamp reveals a final warning.",
      "visual_description": "The Oracle Lamp's flame flares, showing a vision of the bridge collapsing, its eye filled with dread as it whispers of a trap ahead.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "Tin Fox disarms a trigger on the bridge.",
      "visual_description": "Tin Fox scurries onto the stone bridge, its small metal claws working to disable a hidden mechanism beneath the planks, blue eyes focused.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "The armored patrols close in.",
      "visual_description": "Armored figures march onto the bridge from the far side, their visors glowing, as the group races across the middle span.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver creates a mirrored distraction.",
      "visual_description": "The Glass Diver spins his coat, reflecting blinding light from his helmet into the patrols' eyes, buying precious seconds for the escape.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "They cross the bridge to safety.",
      "visual_description": "The group dashes off the bridge's far end as it crumbles behind them, the ruined city fading into dust, the Oracle Lamp's eye finally calm.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox"]
    }
  ]
}

